using System.Text.Json;
using ModelContextProtocol.Server;

[McpServerResourceType]
public static class ConfigResources
{
    private static readonly Dictionary<string, object> AppConfig = new()
    {
        ["app_name"] = "McpHttpServer",
        ["version"] = "1.0.0",
        ["max_connections"] = 100,
        ["features"] = new Dictionary<string, bool>
        {
            ["dark_mode"] = true,
            ["beta_features"] = false,
        },
    };

    [McpServerResource(UriTemplate = "config://app/settings",
        Name = "app-settings",
        MimeType = "application/json")]
    public static string GetAppSettings()
    {
        return JsonSerializer.Serialize(AppConfig, new JsonSerializerOptions { WriteIndented = true });
    }

    [McpServerResource(UriTemplate = "config://app/environment",
        Name = "app-environment",
        MimeType = "application/json")]
    public static string GetEnvironment()
    {
        var env = new
        {
            machine_name = Environment.MachineName,
            os = Environment.OSVersion.ToString(),
            runtime = Environment.Version.ToString(),
            is_64bit = Environment.Is64BitProcess,
        };
        return JsonSerializer.Serialize(env, new JsonSerializerOptions { WriteIndented = true });
    }
}

using ModelContextProtocol.Server;

[McpServerToolType]
public static class ServerTools
{
    [McpServerTool(Name = "echo", Title = "Echo", ReadOnly = true)]
    public static string Echo(string message) => $"Echo: {message}";

    [McpServerTool(Name = "get_timestamp", Title = "Get Timestamp", ReadOnly = true)]
    public static string GetTimestamp() => DateTime.UtcNow.ToString("O");
}

